def _p(
    preset_id: str,
    category: str,
    label: str,
    translation: str,
    tags: list[str],
    *,
    gender: str = "中性",
    part: str = "全身",
    nsfw: bool = False,
    aliases: list[str] | None = None,
    draw_prompt: str | None = None,
    rating: str | None = None,
    intensity: str = "标准",
    materials: list[str] | None = None,
    layer_state: str = "完整",
    color_slots: list[str] | None = None,
    accessories: list[str] | None = None,
    compatibility: list[str] | None = None,
    has_image: bool = True,
) -> dict:
    return {
        "schema_version": 2,
        "id": preset_id,
        "category": category,
        "label": label,
        "translation": translation,
        "tags": tags,
        "gender": gender,
        "part": part,
        "nsfw": nsfw,
        "aliases": aliases or [],
        "draw_prompt": draw_prompt,
        "rating": rating or ("R18" if nsfw else "普通"),
        "intensity": intensity,
        "source": "builtin",
        "materials": materials or [],
        "layer_state": layer_state,
        "color_slots": color_slots or ["primary", "secondary"],
        "accessories": accessories or [],
        "compatibility": compatibility or [],
        "has_image": has_image,
    }


def _shoe(
    preset_id: str,
    label: str,
    translation: str,
    tags: list[str],
    *,
    footwear_type: str,
    gender: str = "女",
    materials: list[str] | None = None,
    accessories: list[str] | None = None,
    aliases: list[str] | None = None,
) -> dict:
    item = _p(
        preset_id,
        "鞋",
        label,
        translation,
        tags,
        gender=gender,
        part="鞋",
        aliases=aliases or [label],
        materials=materials,
        accessories=accessories,
        has_image=False,
    )
    item["footwear_type"] = footwear_type
    return item


def _legwear(
    preset_id: str,
    label: str,
    translation: str,
    tags: list[str],
    *,
    legwear_type: str,
    materials: list[str] | None = None,
    accessories: list[str] | None = None,
    aliases: list[str] | None = None,
    nsfw: bool = False,
    opacity: str = "",
    pattern: str = "",
    top: str = "",
) -> dict:
    item = _p(
        preset_id,
        "袜",
        label,
        translation,
        tags,
        gender="女",
        part="袜",
        nsfw=nsfw,
        aliases=aliases or [label],
        materials=materials,
        accessories=accessories,
        has_image=False,
    )
    item["legwear_type"] = legwear_type
    if opacity:
        item["opacity"] = opacity
    if pattern:
        item["pattern"] = pattern
    if top:
        item["top"] = top
    return item


def _jewelry(
    preset_id: str,
    label: str,
    translation: str,
    tags: list[str],
    *,
    intensity: str = "强化",
    materials: list[str] | None = None,
    accessories: list[str] | None = None,
) -> dict:
    return _p(
        preset_id,
        "配饰",
        label,
        translation,
        tags,
        gender="女",
        part="配饰",
        nsfw=True,
        aliases=[label],
        draw_prompt=f"wearing completed static body jewelry: {', '.join(tags)}",
        intensity=intensity,
        materials=materials or ["金属"],
        accessories=accessories or [label],
        has_image=False,
    )


